    if (amt < minOrd) {
      return { eligible: false, discount: 0, finalPrice: amt, reason: `Order is below min requirement of ₹${minOrd}` };
    }

    let discount = 0;
    if (coupon.type === "percentage") {
      discount = (amt * parseNum(coupon.value)) / 100;
      const maxDisc = parseNum(coupon.maxDiscount);
      if (maxDisc > 0 && discount > maxDisc) {
        discount = maxDisc;
      }
    } else {
      discount = parseNum(coupon.value);
    }

    if (discount > amt) discount = amt;
    const finalPrice = Math.max(0, amt - discount);
    return { eligible: true, discount: Math.round(discount * 100) / 100, finalPrice: Math.round(finalPrice * 100) / 100 };
